package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

const (
	baseDir     = "/var/data/documents"
	maxBodySize = 1 << 20
)

// secretKey is loaded from the environment at startup instead of being
// hardcoded in source, preventing token forgery by anyone with source access.
var secretKey []byte

func loadSecretKey() error {
	v := os.Getenv("HMAC_SECRET_KEY")
	if len(v) < 32 {
		return fmt.Errorf("HMAC_SECRET_KEY must be set and at least 32 bytes")
	}
	secretKey = []byte(v)
	return nil
}

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
}

type Session struct {
	UserID    string
	Role      string
	ExpiresAt time.Time
}

type TokenPayload struct {
	UserID    string `json:"user_id"`
	Role      string `json:"role"`
	ExpiresAt int64  `json:"expires_at"`
}

var store = &SessionStore{
	sessions: make(map[string]*Session),
}

func generateMAC(message []byte) []byte {
	mac := hmac.New(sha256.New, secretKey)
	mac.Write(message)
	return mac.Sum(nil)
}

func createToken(payload *TokenPayload) (string, error) {
	data, err := json.Marshal(payload)
	if err != nil {
		return "", err
	}
	mac := generateMAC(data)
	token := base64.RawURLEncoding.EncodeToString(data) + "." + base64.RawURLEncoding.EncodeToString(mac)
	return token, nil
}

func verifyToken(token string) (*TokenPayload, error) {
	parts := strings.SplitN(token, ".", 2)
	if len(parts) != 2 {
		return nil, fmt.Errorf("invalid token format")
	}

	data, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, fmt.Errorf("invalid payload encoding")
	}

	macBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("invalid mac encoding")
	}

	expectedMAC := generateMAC(data)
	// Verify HMAC using constant-time comparison
	if !hmac.Equal(expectedMAC, macBytes) {
		return nil, fmt.Errorf("invalid signature")
	}

	var payload TokenPayload
	if err := json.Unmarshal(data, &payload); err != nil {
		return nil, fmt.Errorf("invalid payload")
	}

	if time.Now().Unix() > payload.ExpiresAt {
		return nil, fmt.Errorf("token expired")
	}

	return &payload, nil
}

func authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if !strings.HasPrefix(authHeader, "Bearer ") {
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}

		token := strings.TrimPrefix(authHeader, "Bearer ")
		payload, err := verifyToken(token)
		if err != nil {
			http.Error(w, "unauthorized: "+err.Error(), http.StatusUnauthorized)
			return
		}

		r.Header.Set("X-User-ID", payload.UserID)
		r.Header.Set("X-User-Role", payload.Role)
		next(w, r)
	}
}

func handleReadFile(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	requestPath := r.URL.Query().Get("path")
	if requestPath == "" {
		http.Error(w, "path required", http.StatusBadRequest)
		return
	}

	userRole := r.Header.Get("X-User-Role")

	// Sanitize path
	cleaned := filepath.Clean(requestPath)
	if strings.Contains(cleaned, "..") {
		http.Error(w, "invalid path", http.StatusBadRequest)
		return
	}

	// Remove leading separator
	cleaned = strings.TrimPrefix(cleaned, string(filepath.Separator))

	// Determine access directory based on role
	accessDir := baseDir
	if userRole != "admin" {
		accessDir = filepath.Join(baseDir, "public")
	}

	fullPath := filepath.Join(accessDir, cleaned)

	// Resolve symlinks and verify containment
	resolvedBase, err := filepath.EvalSymlinks(accessDir)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	resolvedTarget, err := filepath.EvalSymlinks(fullPath)
	if err != nil {
		http.Error(w, "file not found", http.StatusNotFound)
		return
	}

	if !strings.HasPrefix(resolvedTarget, resolvedBase+string(filepath.Separator)) {
		http.Error(w, "access denied", http.StatusForbidden)
		return
	}

	// Check file info
	info, err := os.Stat(resolvedTarget)
	if err != nil || info.IsDir() {
		http.Error(w, "file not found", http.StatusNotFound)
		return
	}

	if info.Size() > 10*1024*1024 {
		http.Error(w, "file too large", http.StatusRequestEntityTooLarge)
		return
	}

	f, err := os.Open(resolvedTarget)
	if err != nil {
		http.Error(w, "cannot read file", http.StatusInternalServerError)
		return
	}
	defer f.Close()

	w.Header().Set("Content-Type", "application/octet-stream")
	io.Copy(w, io.LimitReader(f, 10*1024*1024))
}

type PermissionRequest struct {
	TargetUser     string `json:"target_user"`
	NewRole        string `json:"new_role"`
	PrivilegeLevel int    `json:"privilege_level"`
}

func handleUpdatePermission(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userRole := r.Header.Get("X-User-Role")

	// Only admins can change roles
	if userRole != "admin" {
		http.Error(w, "admin access required", http.StatusForbidden)
		return
	}

	var req PermissionRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, maxBodySize)).Decode(&req); err != nil {
		http.Error(w, "invalid json", http.StatusBadRequest)
		return
	}

	if req.TargetUser == "" || req.NewRole == "" {
		http.Error(w, "target_user and new_role required", http.StatusBadRequest)
		return
	}

	// Validate role values
	validRoles := map[string]bool{"admin": true, "viewer": true, "editor": true}
	if !validRoles[req.NewRole] {
		http.Error(w, "invalid role", http.StatusBadRequest)
		return
	}

	// Update the role
	store.mu.Lock()
	if sess, exists := store.sessions[req.TargetUser]; exists {
		sess.Role = req.NewRole
	}
	store.mu.Unlock()

	w.WriteHeader(http.StatusOK)
	json.NewEncoder(w).Encode(map[string]string{"status": "updated"})
}

func handleLogin(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var creds struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}

	if err := json.NewDecoder(io.LimitReader(r.Body, maxBodySize)).Decode(&creds); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	// Simplified auth - in production would check against DB with bcrypt
	var role string
	switch creds.Username {
	case "admin":
		if creds.Password == "admin-pass-2024" {
			role = "admin"
		}
	case "user":
		if creds.Password == "user-pass-2024" {
			role = "viewer"
		}
	default:
		http.Error(w, "invalid credentials", http.StatusUnauthorized)
		return
	}

	if role == "" {
		http.Error(w, "invalid credentials", http.StatusUnauthorized)
		return
	}

	payload := &TokenPayload{
		UserID:    creds.Username,
		Role:      role,
		ExpiresAt: time.Now().Add(24 * time.Hour).Unix(),
	}

	token, err := createToken(payload)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	store.mu.Lock()
	store.sessions[creds.Username] = &Session{
		UserID:    creds.Username,
		Role:      role,
		ExpiresAt: time.Now().Add(24 * time.Hour),
	}
	store.mu.Unlock()

	json.NewEncoder(w).Encode(map[string]string{"token": token})
}

func main() {
	if err := loadSecretKey(); err != nil {
		log.Fatalf("failed to load signing key: %v", err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/login", handleLogin)
	mux.HandleFunc("/api/files", authMiddleware(handleReadFile))
	mux.HandleFunc("/api/permissions", authMiddleware(handleUpdatePermission))

	server := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 15 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	log.Printf("Starting server on :8080")
	if err := server.ListenAndServe(); err != nil {
		log.Fatal(err)
	}
}
